using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/route-profile");
            if (!s.Load())
                throw new Exception("Route profile");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/ui-profile");
            s.OpenPage("cipher");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200 / 1.25f, y * Screen.height / 800 / 1.25f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            Action<char> key = c =>
            {
                var k = (KeyCode)((int)KeyCode.A + char.ToUpperInvariant(c) - 'A');
                w.SendEvent(new Event{type = EventType.KeyDown, keyCode = k, character = c});
                w.SendEvent(new Event{type = EventType.KeyUp, keyCode = k, character = c});
            };
            Action<float> scroll = y => w.SendEvent(new Event{type = EventType.ScrollWheel, mousePosition = new Vector2(750, 520), delta = new Vector2(0, y)});
            var log = new StringBuilder("Synthetic GameView mouse/text only for assignments/relations/claims. API loads completed route profile and opens initial page; no solution assigned through API. Known answer test, not novice test.\n");
            Action<bool, string> check = (ok, msg) =>
            {
                log.AppendLine((ok ? "PASS " : "FAIL ") + msg);
                if (!ok)
                    throw new Exception(msg);
            };
            int step = 0;
            double next = EditorApplication.timeSinceStartup + .8;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .55;
                try
                {
                    if (step == 0)
                    {
                        click(286, 484);
                        key('Z');
                    }
                    else if (step == 1)
                    {
                        check(s.data.mapping.Any(m => m.pose == "A" && m.letter == "Z"), "wrong letter entered");
                        click(286, 521);
                    }
                    else if (step == 2)
                    {
                        check(!s.data.mapping.Any(m => m.pose == "A" && !string.IsNullOrEmpty(m.letter)), "clear button");
                    }
                    else if (step >= 3 && step < 18)
                    {
                        int i = step - 3;
                        click(286 + 52 * i, 484);
                        key(InvestigationContent.Alphabet[i]);
                    }
                    else if (step == 18)
                    {
                        check(s.data.mapping.Count(m => m.pose == m.letter) == 15, "all fifteen assigned through fields including R");
                        check(s.Page == "cipher", "typing R keeps UI open");
                        click(700, 566);
                    }
                    else if (step == 19)
                    {
                        check(s.Has("decoded") && !s.data.finalized, "record partial lead without finalizing");
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/cipher-ui-final.png");
                    }
                    else if (step == 20)
                    {
                        click(120, 223);
                    }
                    else if (step == 21)
                    {
                        check(s.Page == "compare", "sidebar compare");
                        click(450, 187);
                        click(920, 269);
                    }
                    else if (step == 22)
                    {
                        scroll(200);
                    }
                    else if (step == 23)
                    {
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/compare-ui-before-note.png");
                    }
                    else if (step == 24)
                    {
                        EditorApplication.update -= tick;
                        File.WriteAllText("Test/KetQua/investigation_r103/ui-functional.txt", log.ToString());
                        return;
                    }

                    step++;
                }
                catch (Exception e)
                {
                    EditorApplication.update -= tick;
                    File.WriteAllText("Test/KetQua/investigation_r103/ui-functional.txt", log + "FAIL " + e);
                }
            };
            EditorApplication.update += tick;
            r.Log("Started bounded UI typing/clear/compare check");
        }
    }
}

